<?php
require_once __DIR__.'/../../includes/staff/auth.php';require_permission('staff.view');verify_csrf();$pdo=staff_db();
if($_SERVER['REQUEST_METHOD']==='POST'&&can('staff.create')){$s=$pdo->prepare("INSERT INTO staff(staff_code,role_id,department_id,branch_id,first_name,last_name,email,phone,password_hash,job_title,hire_date,employment_status,must_change_password,is_active) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,1,1)");$s->execute([trim($_POST['staff_code']),$_POST['role_id'],$_POST['department_id']?:null,$_POST['branch_id']?:null,trim($_POST['first_name']),trim($_POST['last_name']),trim($_POST['email']),trim($_POST['phone']),password_hash($_POST['password']?:'password123',PASSWORD_DEFAULT),trim($_POST['job_title']),$_POST['hire_date']?:null,'active']);flash('success','Staff account created.');staff_redirect('staff/admin/staff-management.php');}
$roles=$pdo->query("SELECT * FROM roles WHERE is_active=1 ORDER BY hierarchy_level")->fetchAll();$deps=$pdo->query("SELECT * FROM departments WHERE is_active=1 ORDER BY name")->fetchAll();$branches=$pdo->query("SELECT * FROM branches WHERE is_active=1")->fetchAll();$rows=$pdo->query("SELECT s.*,r.name role_name,d.name department_name FROM staff s JOIN roles r ON r.id=s.role_id LEFT JOIN departments d ON d.id=s.department_id ORDER BY s.is_active DESC,r.hierarchy_level,s.first_name")->fetchAll();$pageTitle='Staff Management';require __DIR__.'/../../includes/staff/header.php';?>
<main class="staff-content"><div class="page-head"><div><p class="eyebrow">Management</p><h1>Staff management</h1></div></div><?php if(can('staff.create')):?><details class="staff-panel form-details"><summary>Add staff member</summary><form method="post" class="form-grid"><?= csrf_field() ?><label>Staff code<input name="staff_code" required></label><label>First name<input name="first_name" required></label><label>Last name<input name="last_name"></label><label>Email<input type="email" name="email" required></label><label>Phone<input name="phone"></label><label>Job title<input name="job_title"></label><label>Role<select name="role_id"><?php foreach($roles as $r):?><option value="<?= $r['id'] ?>"><?= h($r['name']) ?></option><?php endforeach;?></select></label><label>Department<select name="department_id"><?php foreach($deps as $d):?><option value="<?= $d['id'] ?>"><?= h($d['name']) ?></option><?php endforeach;?></select></label><label>Branch<select name="branch_id"><?php foreach($branches as $b):?><option value="<?= $b['id'] ?>"><?= h($b['name']) ?></option><?php endforeach;?></select></label><label>Hire date<input type="date" name="hire_date"></label><label>Initial password<input name="password" value="password123"></label><button class="btn primary">Create staff</button></form></details><?php endif;?><section class="staff-panel table-panel"><table><thead><tr><th>Staff</th><th>Role</th><th>Department</th><th>Job title</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?= h(trim($r['first_name'].' '.$r['last_name'])) ?></b><small><?= h($r['staff_code'].' · '.$r['email']) ?></small></td><td><?= h($r['role_name']) ?></td><td><?= h($r['department_name']?:'—') ?></td><td><?= h($r['job_title']?:'—') ?></td><td><span class="pill"><?= $r['is_active']?'Active':'Inactive' ?></span></td></tr><?php endforeach;?></tbody></table></section></main><?php require __DIR__.'/../../includes/staff/footer.php';?>
